mapper.select:
select tag_text from pt_tags where
1=1

    and master_id = #{ptTags.masterId}


    and subject_id = #{ptTags.subjectId}


    and tag_text like concat('%',#{ptTags.tagText},'%')


    and "type" = #{ptTags.type}


    and video_id = #{ptTags.videoId}


    and resource_id = #{ptTags.resourceId}


    and channel_id = #{ptTags.channelId}


    and file_id = #{ptTags.fileId}

group by tag_text, create_time
order by create_time desc
